    """
    Evaluates an arithmetic expression using the Shunting Yard algorithm
    by converting the expression to Reverse Polish Notation and then evaluating it.
    """

    def shunting_yard(expression):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output = []
        operators = []
        number = ''

        for char in expression:
            if char.isdigit() or char == '.':
                number += char
            else:
                if number:
                    output.append(float(number))
                    number = ''

                if char in precedence:
                    while (operators and operators[-1] in precedence and
                           precedence[operators[-1]] >= precedence[char]):
                        output.append(operators.pop())
                    operators.append(char)
                elif char == '(':
                    operators.append(char)
                elif char == ')':
                    while operators and operators[-1] != '(':
                        output.append(operators.pop())
                    operators.pop()  # Remove the '('

        if number:
            output.append(float(number))

        while operators:
            output.append(operators.pop())

        return output

    def evaluate_rpn(rpn):
        stack = []
        for token in rpn:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    return evaluate_rpn(shunting_yard(expr.replace(' ', '')))

