    """
    Evaluates an arithmetic expression using a stack-based approach to 
    manage operator precedence and handle parentheses without recursion.
    """

    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        operator = operators.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    values = []
    operators = []
    i = 0
    n = len(expr)

    while i < n:
        char = expr[i]

        if char.isspace():
            i += 1
            continue

        if char.isdigit() or char == '.':
            num = ''
            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                num += expr[i]
                i += 1
            values.append(float(num))
            continue

        if char == '(':
            operators.append(char)

        elif char == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove the '('

        else:
            while (operators and precedence(operators[-1]) >= precedence(char)):
                apply_operator(operators, values)
            operators.append(char)

        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

